import {HAIL_SIZE_LABELS,hailObserved,hailReportState} from './hail-tools.js';
import {esc,valueText,weatherName} from './weather-tools.js';
const $=s=>document.querySelector(s);
const officialURL='https://rischi.protezionecivile.gov.it/it/meteo-idro/';
const interests={auto:['Auto','Quali informazioni devo verificare prima di decidere cosa fare per l’auto? Non suggerire spostamenti durante il maltempo.'],casa:['Casa','Quali informazioni devo verificare per prepararmi al maltempo a casa?'],fuori:['Attività fuori','Quali informazioni devo controllare prima di un’attività all’aperto? Non proporre itinerari sicuri.']};
export function hailEvidence(data,now=Date.now()){
 if(!data||!Number.isFinite(data.updated)||now-data.updated>120000||data.updated>now+60000)return {title:'Segnalazioni da aggiornare',detail:'Il dato non è disponibile o non è abbastanza recente. Non significa assenza di grandine.',fresh:false};
 return {title:data.reports?`${data.reports} segnalazioni · ${data.contributors} account`:'Nessuna segnalazione nelle ultime 2 ore',detail:data.reports?'Sono racconti delle persone. Più post dello stesso account non sono conferme indipendenti.':'Nessuna segnalazione non significa nessun rischio: può mancare chi osserva.',fresh:true};
}
export function hailQuestion(interest){return `Grandine chiara. ${interests[interest]?.[1]||interests.auto[1]} Rispondi con tre parti brevi: cosa dicono le fonti, cosa non sappiamo, cosa verificare adesso. Confronta il bollettino ufficiale, le previsioni e i testi di grandine dichiarata nelle ultime due ore. Distingui i loro orari. Non dedurre probabilità di grandine, traiettorie o minuti all’arrivo dal numero di post. Non hai analizzato radar, foto o video. Nessuna segnalazione non equivale a nessun pericolo. Usa tono sobrio.`}
export function createHail(ctx){
 let data=null,key='',at=0,busyKey='',sequence=0,interest='auto';
 const placeKey=()=>JSON.stringify([ctx.get().place.name,ctx.get().place.latitude,ctx.get().place.longitude,ctx.get().me?.id||'']);
 const active=()=>ctx.get().route==='grandine';
 function snapshot(){return key===placeKey()?data:null}
 function stamp(time){return new Date(time).toLocaleString('it-IT',{timeZone:ctx.get().weather?.timezone||'UTC',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}
 function reportsHTML(){const d=snapshot(),state=hailEvidence(d);return `<div class="hail-source-head"><span>01 / LE PERSONE</span><span class="hail-badge">Dichiarazioni</span></div><h2>${esc(state.title)}</h2><p>${esc(state.detail)}</p><p class="hail-meta">Città dichiarata: ${esc(ctx.get().place.name)}. Non sono indirizzi o punti d’impatto verificati; località omonime possono non essere distinguibili.</p>${state.fresh?`<p class="hail-meta">Consultate il ${esc(stamp(d.updated))} · ${esc(ctx.get().weather?.timezone||'UTC')}</p>${d.truncated?'<p>Mostriamo i 12 post più recenti. Il conteggio comprende tutti i post accessibili della città nelle due ore.</p>':''}<ol class="hail-timeline">${d.posts.map(p=>`<li><time>Osservata ${esc(stamp(hailObserved(p)))}</time><p class="hail-meta">${esc(HAIL_SIZE_LABELS[p.size]||HAIL_SIZE_LABELS.unknown)} · ${esc(hailReportState(p))}<br>${Number(p.confirms)||0} conferme · ${Number(p.disputes)||0} contestazioni · pubblicata ${esc(stamp(p.created))}</p><p>${esc(p.text)}</p><a href="#post:${encodeURIComponent(p.id)}">Leggi e rispondi al post →</a></li>`).join('')}</ol>`:''}`}
 function modelHTML(){const w=ctx.get().weather,c=w?.current;return `<div class="hail-source-head"><span>02 / IL MODELLO</span><span class="hail-badge">Previsione</span></div><h2>${c?weatherName(c.weather_code):'Previsione non disponibile'}</h2>${c?`<p class="hail-model">${valueText(c.temperature_2m,'°')} <span>Vento ${valueText(c.wind_speed_10m,' km/h')}</span></p><p class="hail-meta">Open-Meteo · ${esc(c.time?.replace('T',' '))} · ${esc(w.timezone)}</p>`:''}<p>La pioggia prevista non è una probabilità di grandine. Questo quadro non calcola traiettorie o tempi d’arrivo.</p><a href="#tendenze">Leggi le previsioni →</a><p><a href="https://open-meteo.com/" target="_blank" rel="noopener">Fonte Open-Meteo ↗</a></p>`}
 function page(){return `<section class="atmo-home hail-page"><div class="atmo-heading"><div><p>METEOSOCIAL / GRANDINE</p><h1>Grandine chiara</h1><p data-hail-city>${esc(ctx.get().place.name)}</p></div><button data-search-place>Cambia città</button></div><div class="hail-intro"><h2>Cosa sappiamo. Cosa manca.</h2><p>Persone, previsioni e bollettini: ogni informazione conserva la sua origine.</p></div><div class="hail-toolbar"><button data-hail-refresh>Aggiorna il quadro</button><a href="#grandine-mappa">Grandine sulla mappa</a><a href="#radar">Apri il radar</a><button data-quick="Grandine">Segnala grandine</button><a href="#testimonianza">Testimonianza con foto</a></div><p data-hail-status role="status" class="hail-meta"></p><section aria-label="Bollettino ufficiale"><p class="atmo-kicker">PRIMA DI DECIDERE / LA FONTE UFFICIALE</p><div data-atmo-alert>${ctx.safetyHTML()}</div></section><div class="hail-grid"><section class="atmo-panel" id="hail-reports">${reportsHTML()}</section><section class="atmo-panel" id="hail-model">${modelHTML()}</section></div><section class="atmo-panel hail-ai"><div class="hail-source-head"><span>LENTE IA</span><span class="hail-badge">Spiegazione su richiesta</span></div><h2>Che cosa ti interessa?</h2><div class="hail-interests" aria-label="Argomento della domanda">${Object.entries(interests).map(([id,[label]])=>`<button data-hail-interest="${id}" aria-pressed="${interest===id}">${label}</button>`).join('')}</div><p>Lente confronta previsioni, bollettini e fino a 12 segnalazioni: testo, orari, dimensioni dichiarate e riscontri della community. Ti dice anche quali conclusioni non si possono trarre.</p><button class="button" data-hail-ai>Prepara la domanda per Lente</button><p class="hail-meta">La domanda resta modificabile: premi Invia in Lente per usare l’IA. Foto, video e nomi degli autori non vengono inviati. Le risposte possono contenere errori.</p></section><section class="atmo-panel hail-share"><h2>Condividi un quadro, con le fonti.</h2><p>Invia località, orari e limiti del dato. Chi legge sa a quale momento si riferisce.</p><button data-hail-share>Condividi il riepilogo</button><button data-hail-copy>Copia il riepilogo</button><textarea id="hail-copy-text" aria-label="Riepilogo da copiare" readonly hidden></textarea><p class="hail-meta">Il riepilogo è una fotografia del momento, non un avviso aggiornato automaticamente.</p></section><details class="atmo-tour"><summary>Perché non mostriamo un semaforo di sicurezza?</summary><p>Il numero di post non misura la probabilità di grandine. Più account non dimostrano osservazioni indipendenti. Il radar delle precipitazioni non identifica da solo i chicchi. I bollettini hanno zone e validità proprie. Quando una fonte manca, lo mostriamo.</p><p>Puoi contribuire da un posto protetto: nessuna ricompensa richiede di esporti al maltempo.</p><a href="${officialURL}" target="_blank" rel="noopener">Indicazioni della Protezione Civile ↗</a></details></section>`}
 function paint(){if(!active())return;const city=$('[data-hail-city]');if(city)city.textContent=ctx.get().place.name;const r=$('#hail-reports'),m=$('#hail-model');if(r)r.innerHTML=reportsHTML();if(m)m.innerHTML=modelHTML()}
 async function load(force=false){if(!active())return;const k=placeKey();if(busyKey===k||!force&&key===k&&Date.now()-at<60000){paint();return}busyKey=k;const token=++sequence;paint();const status=$('[data-hail-status]');if(status)status.textContent='Aggiornamento delle segnalazioni…';try{const result=await ctx.api('atlas/hail?'+new URLSearchParams({city:ctx.get().place.name}));if(token!==sequence||k!==placeKey())return;data=result;key=k;at=Date.now();if(active()&&$('[data-hail-status]'))$('[data-hail-status]').textContent='Segnalazioni aggiornate. Il bollettino conserva il proprio orario di emissione.'}catch{if(token!==sequence||k!==placeKey())return;data=null;key=k;at=0;if(active()&&$('[data-hail-status]'))$('[data-hail-status]').textContent='Segnalazioni non disponibili. Puoi riprovare e consultare le altre fonti.'}finally{if(token===sequence){busyKey='';paint()}}}
 function shareText(){const d=snapshot(),state=hailEvidence(d),p=ctx.get().place,w=ctx.get().weather,safety=ctx.safety();return `MeteoSocial · Grandine chiara\n${p.name}\nQuadro consultato: ${new Date().toISOString()} (UTC)\n\nPersone: ${state.title}. ${state.detail}${d&&state.fresh?'\nFonte community · consultata '+new Date(d.updated).toISOString():''}\nBollettino: ${safety?.title||'non verificabile'}${safety?.validDate?' · valido '+safety.validDate:''}${safety?.issued?' · emissione '+safety.issued:''}\n${officialURL}\nPrevisione Open-Meteo: ${w?.current?weatherName(w.current.weather_code)+' · '+w.current.time+' · '+w.timezone:'non disponibile'}\nhttps://open-meteo.com/\n\nNon è una previsione di grandine né una garanzia di sicurezza. I dati possono cambiare.\nApri MeteoSocial e seleziona ${p.name}:\n${location.origin}/#grandine`}
 async function share(copy=false){const text=shareText();if(!copy&&navigator.share)try{await navigator.share({title:'Grandine chiara · MeteoSocial',text});return}catch(e){if(e.name==='AbortError')return}try{await navigator.clipboard.writeText(text);ctx.toast('Riepilogo con fonti copiato.')}catch{const field=$('#hail-copy-text');field.hidden=false;field.value=text;field.focus();field.select();ctx.toast('Seleziona e copia il riepilogo.')}}
 function bind(){if(!active())return;load();$('[data-hail-refresh]').onclick=()=>{load(true);ctx.refreshWeather();$('[data-atmo-alert-retry]')?.click()};$('[data-hail-ai]').onclick=()=>ctx.askAI(hailQuestion(interest));document.querySelectorAll('[data-hail-interest]').forEach(b=>b.onclick=()=>{interest=b.dataset.hailInterest;document.querySelectorAll('[data-hail-interest]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.hailInterest===interest)))});$('[data-hail-share]').onclick=()=>share();$('[data-hail-copy]').onclick=()=>share(true)}
 setInterval(()=>{if(active()&&!document.hidden)load()},60000);document.addEventListener('visibilitychange',()=>{if(active()&&!document.hidden)load()});
 return {page,bind,invalidate(){sequence++;busyKey='';key='';at=0;load(true)},refresh(){if(active()){paint();load()}}};
}
